def format_bytes(n):
    """Return a human-readable size such as '1.5 KB'."""
    n = float(n)
    if n < 1024:
        return f"{int(n)} B"
    units = ["KB", "MB", "GB", "TB", "PB"]
    for i in range(len(units)):
        n /= 1024.0
        if n < 1024 or i == len(units) - 1:
            return f"{n:.1f} {units[i]}"
    return f"{n:.1f} {units[-1]}"
